1	/**
2	 * workflow-runs.ts — find the run a dispatch started, and wait for it to finish.
3	 *
4	 * `dispatchWorkflow` says GitHub accepted a `workflow_dispatch`. That is not the
5	 * same as the deployment having happened: it is a receipt for the request. A
6	 * deployment that creates a release tag dispatches the tag's own deployment and,
7	 * before this module existed, returned success the moment the request was
8	 * accepted. The merge-side run went green while the release it was supposed to
9	 * produce did not exist yet, and the next step in the chain failed looking for it.
10	 *
11	 * ## Which run is the one that was just asked for
12	 *
13	 * `gh workflow run` prints the run URL when it can, but not reliably and not as
14	 * machine-readable output. So the run is found by asking for the newest
15	 * `workflow_dispatch` run of that workflow on that ref. A tag is immutable and is
16	 * dispatched once, so for the tag bridge there is no older run for the same ref to
17	 * confuse it with. The ref is also what `gh run list --branch` matches for a tag:
18	 * GitHub reports a tag run's `headBranch` as the tag name.
19	 *
20	 * ## Why polling rather than `gh run watch`
21	 *
22	 * `gh run watch` refuses to authenticate with a fine-grained PAT, because it wants
23	 * `checks: read` and no such fine-grained permission exists. The job that dispatches
24	 * holds an Actions token, which would work, but the helper stays a plain poll so a
25	 * different caller is not tied to that. It also makes the two questions separate:
26	 * "did the run appear" and "how did it end".
27	 */
28	import { gh, ghRead } from "./gh.ts";
29	
30	/** A workflow run, as much of it as the wait needs. */
31	export interface WorkflowRun {
32	  readonly id: number;
33	  readonly status: string;
34	  readonly conclusion: string | null;
35	}
36	
37	/** How long a wait may last, and how often it asks. */
38	export interface RunWaitOptions {
39	  /** Number of reads, one after the first. */
40	  readonly attempts: number;
41	  /** Milliseconds between reads. */
42	  readonly intervalMs: number;
43	}
44	
45	/**
46	 * Test seam and operational bound, in the same shape as `ATOMATON_FAKE_GH`.
47	 *
48	 * The default is calibrated against a release publish: the tag deployment has a
49	 * sixty-minute job timeout, and the merge-side run holds its runner while it waits.
50	 * A test sets both to one attempt and no interval, so it exercises the answer
51	 * rather than the clock.
52	 */
53	export const RUN_WAIT_ATTEMPTS_VAR = "ATOMATON_RUN_WAIT_ATTEMPTS";
54	export const RUN_WAIT_INTERVAL_MS_VAR = "ATOMATON_RUN_WAIT_INTERVAL_MS";
55	
56	const DEFAULT_ATTEMPTS = 420;
57	const DEFAULT_INTERVAL_MS = 10_000;
58	
59	function positiveInt(raw: string | undefined, fallback: number): number {
60	  const value = Number((raw ?? "").trim());
61	  return Number.isInteger(value) && value > 0 ? value : fallback;
62	}
63	
64	function nonNegativeInt(raw: string | undefined, fallback: number): number {
65	  const value = Number((raw ?? "").trim());
66	  return Number.isInteger(value) && value >= 0 ? value : fallback;
67	}
68	
69	/** The wait bounds this process was configured with. */
70	export function runWaitOptions(env: NodeJS.ProcessEnv = process.env): RunWaitOptions {
71	  return {
72	    attempts: positiveInt(env[RUN_WAIT_ATTEMPTS_VAR], DEFAULT_ATTEMPTS),
73	    intervalMs: nonNegativeInt(env[RUN_WAIT_INTERVAL_MS_VAR], DEFAULT_INTERVAL_MS),
74	  };
75	}
76	
77	function parseRun(raw: unknown): WorkflowRun | null {
78	  if (typeof raw !== "object" || raw === null) return null;
79	  const record = raw as Record<string, unknown>;
80	  if (typeof record.databaseId !== "number" || typeof record.status !== "string") return null;
81	  return {
82	    id: record.databaseId,
83	    status: record.status,
84	    conclusion: typeof record.conclusion === "string" ? record.conclusion : null,
85	  };
86	}
87	
88	/**
89	 * The newest `workflow_dispatch` run of `workflow` on `ref`, or null when there is
90	 * none yet.
91	 *
92	 * Null rather than throwing for the same reason `readTagNames` returns null: "no run
93	 * yet" and "the question could not be asked" are both non-answers, and the caller
94	 * retries either.
95	 */
96	export function newestDispatchRun(repo: string, workflow: string, ref: string): WorkflowRun | null {
97	  const { code, stdout } = ghRead(
98	    "run",
99	    "list",
100	    "--repo",
101	    repo,
102	    "--workflow",
103	    workflow,
104	    "--branch",
105	    ref,
106	    "--event",
107	    "workflow_dispatch",
108	    "--limit",
109	    "1",
110	    "--json",
111	    "databaseId,status,conclusion",
112	  );
113	  if (code !== 0) return null;
114	  try {
115	    const runs = JSON.parse(stdout || "[]") as unknown;
116	    if (!Array.isArray(runs)) return null;
117	    return parseRun(runs[0]);
118	  } catch {
119	    return null;
120	  }
121	}
122	
123	/** Wait for the run a dispatch started to appear. */
124	export function waitForDispatchRun(
125	  repo: string,
126	  workflow: string,
127	  ref: string,
128	  options: RunWaitOptions = runWaitOptions(),
129	): WorkflowRun | null {
130	  for (let attempt = 0; attempt < options.attempts; attempt += 1) {
131	    const run = newestDispatchRun(repo, workflow, ref);
132	    if (run) return run;
133	    if (attempt + 1 < options.attempts) Bun.sleepSync(options.intervalMs);
134	  }
135	  return null;
136	}
137	
138	/**
139	 * Wait for `runId` to finish, and return how it ended.
140	 *
141	 * A run that has completed is returned even when its conclusion is not `success`;
142	 * deciding what a failure means belongs to the caller, and the dispatch script is
143	 * the one that fails its job over it.
144	 */
145	export function waitForRunCompletion(
146	  repo: string,
147	  runId: number,
148	  options: RunWaitOptions = runWaitOptions(),
149	): WorkflowRun | null {
150	  for (let attempt = 0; attempt < options.attempts; attempt += 1) {
151	    const { code, stdout } = ghRead(
152	      "run",
153	      "view",
154	      String(runId),
155	      "--repo",
156	      repo,
157	      "--json",
158	      "databaseId,status,conclusion",
159	    );
160	    if (code === 0) {
161	      try {
162	        const run = parseRun(JSON.parse(stdout || "{}") as unknown);
163	        if (run && run.status === "completed") return run;
164	      } catch {
165	        // A malformed answer is not the run having finished; ask again.
166	      }
167	    }
168	    if (attempt + 1 < options.attempts) Bun.sleepSync(options.intervalMs);
169	  }
170	  return null;
171	}

