1	/**
2	 * gh.ts — thin wrappers around the `gh` CLI and `git`. The one canonical
3	 * copy shared by every script and MCP server in this repo (workflow-invoked
4	 * `src/entrypoints/machinery/**` and Atomaton-tool-invoked `src/entrypoints/tools/**`
5	 * alike) -- see build-dist.ts for how this stays true in the deployed
6	 * output despite living in one shared place at dev time.
7	 */
8	
9	export interface RunResult {
10	  code: number;
11	  stdout: string;
12	  stderr: string;
13	}
14	
15	function run(cmd: string[]): RunResult {
16	  const proc = Bun.spawnSync({
17	    cmd,
18	    stdout: "pipe",
19	    stderr: "pipe",
20	  });
21	  return {
22	    code: proc.exitCode ?? 1,
23	    stdout: proc.stdout ? proc.stdout.toString("utf8").trim() : "",
24	    stderr: proc.stderr ? proc.stderr.toString("utf8").trim() : "",
25	  };
26	}
27	
28	/**
29	 * What to invoke for `gh`, as an argv prefix.
30	 *
31	 * `gh` everywhere except a test, which points this at its fake. It is an env var
32	 * rather than a directory on PATH because PATH does not work for this on Windows: a
33	 * bare command resolves through PATHEXT, so the fake has to carry an extension, and
34	 * the only extensions Windows will run are a compiled `.exe` or a `.cmd` — which
35	 * Bun and Node refuse to pass arguments containing `"` or `|` to, on purpose, since
36	 * cmd.exe would re-parse them. Half this repository's `gh` calls carry a jq
37	 * expression, so a `.cmd` shim rejects them.
38	 *
39	 * The fake was on PATH, and on Windows it was silently never used: what ran was the
40	 * real `gh`, with the developer's own credentials, against this repository. This
41	 * removes the resolution step that made that possible rather than fixing it, because
42	 * the failure mode of getting it wrong is writing to a live repository.
43	 *
44	 * Named for what it is. This is a test seam and nothing else: it takes a script, run by
45	 * the runtime already running, so it cannot be mistaken for configuration naming where
46	 * a real installation keeps its CLI.
47	 */
48	function ghCommand(): string[] {
49	  const fake = (process.env.ATOMATON_FAKE_GH ?? "").trim();
50	  // `process.execPath`, not `"bun"`. Resolving the name has the same problem one layer
51	  // down: a Bun installed through npm is reached by `bun.cmd`, so spawning `bun` hits
52	  // the same refusal for the same arguments. The absolute path of the runtime already
53	  // running this cannot be a shim.
54	  return fake ? [process.execPath, fake] : ["gh"];
55	}
56	
57	/** Run the `gh` CLI. Inherits GH_TOKEN from the parent environment. */
58	export function gh(...args: string[]): RunResult {
59	  return run([...ghCommand(), ...args]);
60	}
61	
62	/**
63	 * Run one `gh` command as `token`, rather than as the ambient `GH_TOKEN`.
64	 *
65	 * For the caller that must act as an identity the workflow does not hold: the
66	 * update opens its pull request and merges it under the update token, because
67	 * GitHub starts no `pull_request` run for a pull request the workflow's own
68	 * token opened and no `push` for a merge it made -- and the check the ruleset
69	 * requires and the deploy the merge chains to are exactly those events. The
70	 * token is an identity that starts runs; the workflow's token is not.
71	 *
72	 * The environment is built for one process and dies with it, the same rule
73	 * `gitRunWith` states: assigning `GH_TOKEN` into `process.env` would leave every
74	 * later `gh` in this script acting as the token, which is a decision the caller
75	 * makes per call or not at all.
76	 */
77	export function ghAs(token: string, ...args: string[]): RunResult {
78	  const proc = Bun.spawnSync({
79	    cmd: [...ghCommand(), ...args],
80	    stdout: "pipe",
81	    stderr: "pipe",
82	    env: { ...process.env, GH_TOKEN: token },
83	  });
84	  return {
85	    code: proc.exitCode ?? 1,
86	    stdout: proc.stdout ? proc.stdout.toString("utf8").trim() : "",
87	    stderr: proc.stderr ? proc.stderr.toString("utf8").trim() : "",
88	  };
89	}
90	
91	/**
92	 * Run a READ through `gh`, treating an upstream failure as no answer rather than as
93	 * an answer of "no".
94	 *
95	 * GitHub returned `HTTP 504` for one `gh api repos/.../pulls/427` call and the run
96	 * died on it: the reviewer never started, and the pull request carried a red check
97	 * for a defect in neither the code nor the machinery. There is nothing to learn from
98	 * a 504 and nothing for an agent to do about it.
99	 *
100	 * Reads only, which is the whole reason this is a separate function rather than a
101	 * change to `gh` itself. A mutation that returns 502 may well have been applied, and
102	 * the invariants here are the kind a second attempt breaks -- one comment per run,
103	 * one dispatch per handoff. So the retry has to be asked for, by a caller that knows
104	 * its call changes nothing.
105	 *
106	 * Three attempts, widening, because the point is to outlast a blip rather than to
107	 * sit out an outage: a run holds a runner while it sleeps.
108	 */
109	export function ghRead(...args: string[]): RunResult {
110	  let result = gh(...args);
111	  for (const delay of [2_000, 6_000]) {
112	    if (result.code === 0 || !looksTransient(result)) return result;
113	    console.error(
114	      `::warning::gh ${args.slice(0, 2).join(" ")} failed transiently, retrying: ${result.stderr || result.stdout}`,
115	    );
116	    Bun.sleepSync(delay);
117	    result = gh(...args);
118	  }
119	  return result;
120	}
121	
122	/**
123	 * Whether a failure came from the far end rather than from the request.
124	 *
125	 * A 404 is an answer; a 504 is the absence of one. 429 belongs here as well: it is a
126	 * request to wait, and waiting is what a retry does.
127	 */
128	export function looksTransient(result: RunResult): boolean {
129	  const text = `${result.stderr} ${result.stdout}`;
130	  // Character classes rather than shorthand: this line has lost a backslash to
131	  // tooling twice, and `5dd` compiles just as happily as the version that works.
132	  if (/HTTP (429|5[0-9][0-9])(?![0-9])/.test(text)) return true;
133	  return /(timeout|timed out|connection reset|unexpected EOF|TLS handshake|temporary failure)/i.test(text);
134	}
135	
136	/**
137	 * Run `gh` and keep its stdout as bytes.
138	 *
139	 * `gh` above decodes stdout as UTF-8 and trims it, which is right for JSON and
140	 * ruinous for anything else: a PNG through that comes out as replacement
141	 * characters with its ends shaved off. Anything binary — an attached image, a
142	 * downloaded asset — has to come through here instead.
143	 */
144	export function ghBytes(...args: string[]): { code: number; bytes: Uint8Array } {
145	  const proc = Bun.spawnSync({ cmd: [...ghCommand(), ...args], stdout: "pipe", stderr: "pipe" });
146	  return { code: proc.exitCode ?? 1, bytes: proc.stdout ?? new Uint8Array() };
147	}
148	
149	/**
150	 * Run `gh` and parse its stdout as JSON. Throws on non-zero exit.
151	 *
152	 * `T | null`, because empty stdout produces `null` and the signature used to say
153	 * `T`. `null as T` is a cast that makes the type system agree with a claim that
154	 * is not true: the one production caller defends with `?? []`, and the next one
155	 * would have had no reason to.
156	 */
157	export function ghJson<T = unknown>(...args: string[]): T | null {
158	  const { code, stdout, stderr } = gh(...args);
159	  if (code !== 0) {
160	    throw new Error(`gh ${args.join(" ")}: ${stderr || stdout}`);
161	  }
162	  return stdout ? (JSON.parse(stdout) as T) : null;
163	}
164	
165	/** The argv both GraphQL entry points build, so the two cannot drift. */
166	function graphqlArgs(query: string, variables: Record<string, string | number>): string[] {
167	  const args = ["api", "graphql", "-f", `query=${query}`];
168	  for (const [key, value] of Object.entries(variables)) {
169	    args.push("-F", `${key}=${value}`);
170	  }
171	  return args;
172	}
